//! Cargo-driven `msxml3.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x70430000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fec5000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fec5000000u64)),
        o => panic!("msxml3-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:libxml2", "sdk/lib/3rdparty/libwin-iconv/libiconv.a", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:zlib", "import:libxslt", "import:urlmon", "import:ws2_32", "import:shlwapi", "import:bcrypt", "import:oleaut32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "body"],
        "x86_64" => &["engine:c:libxml2", "sdk/lib/3rdparty/libwin-iconv/libiconv.a", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:zlib", "import:libxslt", "import:urlmon", "import:ws2_32", "import:shlwapi", "import:bcrypt", "import:oleaut32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "body"],
        "aarch64" => &["engine:c:libxml2", "sdk/lib/3rdparty/libwin-iconv/libiconv.a", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:zlib", "import:libxslt", "import:urlmon", "import:ws2_32", "import:shlwapi", "import:bcrypt", "import:oleaut32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/msxml3",
        "dll/win32/msxml3",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/libxslt/include",
        "sdk/lib/pseh/include",
        "vendor/libxml2/include",
        "vendor/libxml2/include/libxml",
        "vendor/libwin-iconv",
        "vendor/zlib/include",
        "sdk/lib/tdilib",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "COM_NO_WINDOWS_H",
        "LIBXML_STATIC",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "_WINE",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("msxml3_shims", &["dll/win32/msxml3/attribute.c", "dll/win32/msxml3/bsc.c", "dll/win32/msxml3/cdata.c", "dll/win32/msxml3/comment.c", "dll/win32/msxml3/dispex.c", "dll/win32/msxml3/docfrag.c", "dll/win32/msxml3/doctype.c", "dll/win32/msxml3/domdoc.c", "dll/win32/msxml3/domimpl.c", "dll/win32/msxml3/element.c", "dll/win32/msxml3/entityref.c", "dll/win32/msxml3/httprequest.c", "dll/win32/msxml3/main.c", "dll/win32/msxml3/mxnamespace.c", "dll/win32/msxml3/mxwriter.c", "dll/win32/msxml3/node.c", "dll/win32/msxml3/nodelist.c", "dll/win32/msxml3/nodemap.c", "dll/win32/msxml3/parseerror.c", "dll/win32/msxml3/pi.c", "dll/win32/msxml3/reactos.c", "dll/win32/msxml3/saxreader.c", "dll/win32/msxml3/schema.c", "dll/win32/msxml3/selection.c", "dll/win32/msxml3/stylesheet.c", "dll/win32/msxml3/text.c", "dll/win32/msxml3/xdr.c", "dll/win32/msxml3/xmldoc.c", "dll/win32/msxml3/xmlelem.c", "dll/win32/msxml3/xmlparser.c", "dll/win32/msxml3/xmlview.c", "dll/win32/msxml3/factory.c", "dll/win32/msxml3/uuid.c", "dll/win32/msxml3/xslpattern.yy.c", "dll/win32/msxml3/xslpattern.tab.c"])
        .rc("dll/win32/msxml3/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/msxml3/msxml3.spec", "msxml3.dll")
        .spec_stubs()
        .import_lib("vendor/libxslt/libxslt.spec", "libxslt.dll", "libxslt")
        .import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/bcrypt/bcrypt.spec", "bcrypt.dll", "bcrypt")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
